class Solution {
public:
    int climbStairs(int n, vector<int>& costs) {
        long long dp[4] = {};
        for (int j = 1; j <= n; j++) {
            long long best = dp[(j - 1) % 4] + costs[j - 1] + 1;
            if (j >= 2) best = min(best, dp[(j - 2) % 4] + costs[j - 1] + 4);
            if (j >= 3) best = min(best, dp[(j - 3) % 4] + costs[j - 1] + 9);
            dp[j % 4] = best;
        }
        return (int)dp[n % 4];
    }
};
